 static void golden(String path)throws Exception{tests++;JSONObject vector=new JSONObject(Files.readString(Path.of(path)));byte[] body=NodeReleaseManifest.base64(vector.getString("manifest"),384),signature=NodeReleaseManifest.base64(vector.getString("signature"),72);NodeReleaseManifest.verify(NodeReleaseManifest.publicKey(),NodeReleaseManifest.ARTIFACT_DOMAIN,body,signature);check(body.length==384&&ByteBuffer.wrap(body).getInt(16)==1024);if(NodeReleaseManifest.allZero(body,72,92)){denies(()->NodeReleaseManifest.checked(body,signature));return;}NodeReleaseManifest trusted=NodeReleaseManifest.checked(body,signature);File fake=new File(work,"non-executable.bin");byte[] data=new byte[1024];Arrays.fill(data,(byte)'X');Files.write(fake.toPath(),data);denies(()->NodeFirmwareImage.checked(fake,trusted));}
